-- SDKONGRE requested banner, corporate pages, page content and service content update
begin;
insert into public.site_settings (key, locale, value_json)
values (
  'global',
  'tr',
  '{"hero":{"poster":"/media/headers/anasayfa.webp","secondaryButtonUrl":"/kurumsal/hakkimizda"},"footer":{"description":"Doğru İş Ortakları ile Kusursuz Sonuçlar"}}'::jsonb
)
on conflict (key, locale) do update
set value_json =
  jsonb_set(
    jsonb_set(
      jsonb_set(
        public.site_settings.value_json,
        '{hero,poster}',
        to_jsonb('/media/headers/anasayfa.webp'::text),
        true
      ),
      '{hero,secondaryButtonUrl}',
      to_jsonb('/kurumsal/hakkimizda'::text),
      true
    ),
    '{footer,description}',
    to_jsonb('Doğru İş Ortakları ile Kusursuz Sonuçlar'::text),
    true
  ),
  updated_at = now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('about','tr','Hakkımızda','hakkimizda','KURUMSAL','Organizasyon Yönetiminde Güvenilir ve Stratejik Çözüm Ortağınız','{"headline":"Organizasyon Yönetiminde Güvenilir ve Stratejik Çözüm Ortağınız","paragraphs":["SD Kongre, kongre, sempozyum, kurumsal toplantı, eğitim programı, lansman, fuar, sergi, çalıştay ve seyahat organizasyonlarında uçtan uca hizmet sunan profesyonel bir organizasyon ve etkinlik yönetim şirketidir.","Günümüzde başarılı bir organizasyon yalnızca iyi bir fikirden ibaret değildir. Başarı; doğru planlama, güçlü koordinasyon, etkin bütçe yönetimi, deneyimli operasyon ekipleri ve kusursuz uygulama süreçleri ile mümkün olmaktadır. SD Kongre olarak tam da bu noktada devreye giriyor, kurumların tüm organizasyon süreçlerini tek merkezden yöneterek iş yükünü azaltıyor, verimliliği artırıyor ve hedeflerine ulaşmalarına katkı sağlıyoruz.","Kurulduğumuz günden bu yana temel amacımız, organizasyon yönetimini daha sistematik, daha ölçülebilir ve daha sürdürülebilir hale getirmektir. Bir organizasyonun yalnızca etkinlik gününde değil, fikir aşamasından sonuç raporuna kadar geçen tüm süreçlerinin aynı profesyonellik anlayışıyla yönetilmesi gerektiğine inanıyoruz.","Bu anlayış doğrultusunda; stratejik planlama, proje yönetimi, bütçe kontrolü, tedarikçi koordinasyonu, kayıt ve katılımcı yönetimi, konaklama ve seyahat planlaması, dijital altyapı çözümleri, operasyon yönetimi, veri analizi ve raporlama süreçlerinin tamamını profesyonel ekiplerimizle yürütüyor, kurumlarımıza zaman ve maliyet avantajı sağlıyoruz.","Her organizasyon bizim için bağımsız bir projedir. Bu nedenle standart çözümler yerine sektör, kurum yapısı, hedef kitle ve proje hedeflerine göre özel çözümler geliştiriyor; organizasyonları yalnızca gerçekleştirmiyor, aynı zamanda stratejik bir başarı hikayesine dönüştürüyoruz.","Bugün kamu kurumlarından üniversitelere, sağlık kuruluşlarından meslek örgütlerine, derneklerden özel sektör markalarına kadar geniş bir müşteri portföyüne hizmet veriyor; her projemizde aynı kalite standartlarını koruyarak güvenilir iş ortaklıkları kuruyoruz.","SD Kongre olarak biz, yalnızca etkinlik düzenleyen bir firma değil; kurumların hedeflerine ulaşmasını sağlayan, süreçleri kolaylaştıran ve başarıyı görünür hale getiren güçlü bir çözüm ortağıyız."],"values":[],"heroImage":"/media/corporate/hakkimizda.webp"}'::jsonb,'published'::public.content_status,'{"title":"Hakkımızda","description":"Organizasyon Yönetiminde Güvenilir ve Stratejik Çözüm Ortağınız"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('story','tr','Hikayemiz','hikayemiz','KURUMSAL','Bir Organizasyondan Çok Daha Fazlasını İnşa Ettik','{"headline":"Bir Organizasyondan Çok Daha Fazlasını İnşa Ettik","paragraphs":["SD Kongre''nin hikayesi, organizasyon sektöründe sıklıkla karşılaşılan bir soruna çözüm üretme isteğiyle başladı.","Kurumlar büyük organizasyonlar planlarken çoğu zaman farklı tedarikçiler, farklı operasyon ekipleri ve birbirinden bağımsız süreçlerle çalışmak zorunda kalıyor; bu durum hem zaman kaybına hem de maliyetlerin kontrol edilmesinde ciddi zorluklara neden oluyordu.","Biz ise bu karmaşık yapıyı daha yönetilebilir hale getirmek için yola çıktık.","Kuruluşumuzun temelinde; organizasyon süreçlerini tek çatı altında toplayan, teknolojiyle destekleyen ve profesyonel proje yönetimi yaklaşımıyla yöneten bir sistem kurma fikri bulunmaktadır.","İlk günden itibaren hedefimiz yalnızca organizasyon düzenlemek olmadı. Süreçleri analiz eden, riskleri öngören, operasyonları yöneten, verileri raporlayan ve müşterilerine ölçülebilir sonuçlar sunan bir organizasyon yönetim modeli oluşturmayı hedefledik.","Bu vizyon doğrultusunda teknoloji yatırımlarımızı artırdık, operasyon ağımızı geliştirdik ve organizasyon yönetimini klasik hizmet anlayışının ötesine taşıdık.","Yıllar içerisinde gerçekleştirdiğimiz kongreler, sempozyumlar, bilimsel toplantılar, eğitim programları, kurumsal etkinlikler, fuarlar ve lansman projeleri sayesinde yalnızca operasyonel deneyim değil, aynı zamanda güçlü bir kurumsal bilgi birikimi oluşturduk.","Bugün Türkiye''nin farklı şehirlerinde yürüttüğümüz başarılı projelerle sektörün güvenilir markalarından biri haline gelmiş bulunuyoruz.","Ancak bizim için başarı; tamamlanan organizasyon sayısından çok, müşterilerimizin bize duyduğu güven, tekrar çalışma tercihleri ve tavsiyeleridir.","Çünkü her başarılı organizasyonun sonunda yalnızca bir etkinlik değil, uzun vadeli bir iş ortaklığı doğduğuna inanıyoruz."],"values":[],"heroImage":"/media/corporate/hikayemiz.webp"}'::jsonb,'published'::public.content_status,'{"title":"Hikayemiz","description":"Bir Organizasyondan Çok Daha Fazlasını İnşa Ettik"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('mission','tr','Misyonumuz','misyon','KURUMSAL','','{"headline":"","paragraphs":["Kurumların ihtiyaçlarına özel, yenilikçi, sürdürülebilir ve sonuç odaklı organizasyon çözümleri geliştirerek her projeyi uluslararası kalite standartlarında hayata geçirmek.","Planlama gücümüzü, operasyonel deneyimimizi, teknolojik altyapılarımızı ve uzman insan kaynağımızı bir araya getirerek müşterilerimize maksimum verimlilik, minimum operasyonel yük ve ölçülebilir başarı sunmak.","Her organizasyonu, müşterilerimizin kurumsal hedeflerine ulaşmasını sağlayan stratejik bir yatırım olarak değerlendiriyor ve bu doğrultuda değer üretmeye odaklanıyoruz."],"values":[],"heroImage":"/media/corporate/misyon.webp"}'::jsonb,'published'::public.content_status,'{"title":"Misyonumuz","description":"Kurumların ihtiyaçlarına özel, yenilikçi, sürdürülebilir ve sonuç odaklı organizasyon çözümleri geliştirerek her projeyi uluslararası kalite standartlarında hayata geçirmek."}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('vision','tr','Vizyonumuz','vizyon','KURUMSAL','','{"headline":"","paragraphs":["Kongre, etkinlik ve organizasyon yönetimi sektöründe yenilikçi yaklaşımı, güçlü teknoloji altyapısı, sürdürülebilir operasyon modeli ve yüksek hizmet kalitesi ile Türkiye''nin en güçlü ve en çok tercih edilen organizasyon yönetim markalarından biri olmak.","Ulusal ve uluslararası ölçekte yürütülen projelerde kalite, güven, şeffaflık ve operasyonel mükemmeliyet denildiğinde akla gelen ilk çözüm ortağı haline gelmek.","Sektöre yön veren uygulamalar geliştirerek organizasyon yönetiminin geleceğini şekillendiren öncü markalar arasında yer almak."],"values":[],"heroImage":"/media/corporate/vizyon.webp"}'::jsonb,'published'::public.content_status,'{"title":"Vizyonumuz","description":"Kongre, etkinlik ve organizasyon yönetimi sektöründe yenilikçi yaklaşımı, güçlü teknoloji altyapısı, sürdürülebilir operasyon modeli ve yüksek hizmet kalitesi ile Türkiye''nin en güçlü ve en çok tercih edilen organizasyon yönetim markalarından biri olmak."}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('values','tr','Değerlerimiz','degerlerimiz','KURUMSAL','Başarıya Giden Yolun Temel İlkeleri','{"headline":"Başarıya Giden Yolun Temel İlkeleri","paragraphs":["SD Kongre olarak gerçekleştirdiğimiz her organizasyonun merkezinde yalnızca operasyonel mükemmeliyet değil; güçlü değerler, sürdürülebilir iş anlayışı ve uzun vadeli güven ilişkileri bulunmaktadır. İş yapış şeklimizi belirleyen bu değerler, müşterilerimizle kurduğumuz her iş birliğinin temelini oluşturur.","Kurulduğumuz günden bu yana tüm projelerimizi aynı profesyonel yaklaşım ve sorumluluk bilinciyle yönetiyor, her adımda kurumlarımıza değer katmayı hedefliyoruz."],"values":[{"title":"Güven","description":"Her Başarılı İş Birliğinin Temelinde Güven Yatar. Bizim için güven, yalnızca bir değer değil; tüm faaliyetlerimizin temelidir. Müşterilerimize verdiğimiz sözleri zamanında yerine getirir, süreçleri şeffaf şekilde yönetir ve her aşamada açık iletişim kurarız. Organizasyonların en kritik anlarında dahi çözüm odaklı yaklaşımımızı korur, sorumluluğumuzu eksiksiz şekilde yerine getiririz. Uzun yıllara dayanan müşteri ilişkilerimizin ve tekrar eden iş birliklerimizin arkasındaki en büyük güç, kazandığımız güvendir."},{"title":"Şeffaflık","description":"Her Süreçte Açık ve Hesap Verebilir Yönetim. Başarılı organizasyonların temelinde açık iletişim ve şeffaf süreç yönetimi bulunmaktadır. Bütçe planlamasından satın alma süreçlerine, tedarikçi yönetiminden raporlamaya kadar tüm aşamaları müşterilerimizle paylaşırız. Harcamalar, planlamalar ve operasyonel süreçler her zaman kontrol edilebilir ve izlenebilir yapıdadır. Bu yaklaşım sayesinde müşterilerimiz organizasyonun her aşamasına hakim olur ve süreçleri güvenle takip edebilir."},{"title":"Profesyonellik","description":"Her Projeye Aynı Ciddiyet ve Sorumlulukla Yaklaşıyoruz. Küçük bir toplantı da büyük ölçekli bir uluslararası kongre de bizim için aynı öneme sahiptir. Her projeye titizlikle hazırlanır, detayları önceden planlar ve süreçleri uzman ekiplerimizle yönetiriz. Karşılaşılabilecek riskleri önceden değerlendirerek alternatif çözümler geliştirir ve organizasyonların kesintisiz ilerlemesini sağlarız. Profesyonellik anlayışımız, yalnızca etkinlik gününde değil, projenin başlangıcından sonuç raporuna kadar tüm süreçlerde kendini göstermektedir."},{"title":"Müşteri Odaklılık","description":"Önce Dinliyor, Sonra Çözüm Üretiyoruz. Her kurumun ihtiyaçlarının farklı olduğuna inanıyoruz. Bu nedenle hazır kalıplar yerine müşterilerimizin hedeflerini, beklentilerini ve önceliklerini analiz ederek kurumlara özel çözümler geliştiriyoruz. Başarımızı yalnızca tamamlanan organizasyonlarla değil, müşterilerimizin memnuniyeti ve hedeflerine ulaşmasıyla ölçüyoruz. Her projeyi kendi projemiz gibi sahipleniyor ve maksimum katma değer üretmeye odaklanıyoruz."},{"title":"Yenilikçilik","description":"Sürekli Gelişiyor, Sürekli Daha İyisini Arıyoruz. Organizasyon sektörü sürekli değişmekte ve gelişmektedir. SD Kongre olarak yeni teknolojileri, global organizasyon trendlerini ve sektördeki yenilikleri yakından takip ediyoruz. Dijital kayıt sistemlerinden hibrit etkinlik çözümlerine, QR kod uygulamalarından veri analiz araçlarına kadar yenilikçi teknolojileri organizasyon süreçlerine entegre ediyoruz. Amacımız, müşterilerimize yalnızca bugünün değil, geleceğin organizasyon çözümlerini sunmaktır."},{"title":"Kalite","description":"Mükemmelliği Standart Haline Getiriyoruz. Kalite anlayışımız, sunduğumuz her hizmetin merkezinde yer alır. Planlamadan operasyona, teknik altyapıdan katılımcı deneyimine kadar tüm süreçlerde yüksek standartlarla çalışırız. Her organizasyonu detaylı kontrol mekanizmalarıyla yönetir, mükemmel sonuçlar elde etmek için sürekli iyileştirme yaklaşımını benimseriz. Bizim için kalite, bir hedef değil; vazgeçilmez bir çalışma prensibidir."},{"title":"Sürdürülebilirlik","description":"Bugünü Yönetirken Geleceği de Düşünüyoruz. Kaynakların doğru kullanılması ve süreçlerin verimli yönetilmesi başarılı organizasyonların temel unsurlarından biridir. SD Kongre olarak çevresel, ekonomik ve operasyonel sürdürülebilirliği organizasyon yönetiminin ayrılmaz bir parçası olarak görüyoruz. Dijital çözümleri yaygınlaştırıyor, israfı azaltıyor ve kaynakların verimli kullanımını destekleyen uygulamalar geliştiriyoruz. Sürdürülebilir yaklaşımımız sayesinde hem müşterilerimize hem de gelecek nesillere karşı sorumluluğumuzu yerine getiriyoruz."},{"title":"Takım Ruhu","description":"Başarı, Güçlü Ekiplerin Ortak Üretimidir. Başarılı organizasyonlar bireysel çabalarla değil, uyum içerisinde çalışan ekiplerin ortak başarısıyla ortaya çıkar. Proje yöneticilerimizden saha ekiplerimize, teknik uzmanlarımızdan çözüm ortaklarımıza kadar tüm paydaşlarımızla ortak hedef doğrultusunda hareket ediyoruz. İş birliği kültürünü destekliyor, iletişimin gücüne inanıyor ve ekip ruhunu başarımızın önemli bir parçası olarak görüyoruz."},{"title":"Sonuç Odaklılık","description":"Hedefimiz Etkinlik Değil, Başarıdır. Her organizasyonun arkasında ulaşılması gereken kurumsal hedefler bulunmaktadır. Bu nedenle yalnızca organizasyonu gerçekleştirmeye değil, organizasyonun sağlayacağı sonuçlara odaklanıyoruz. Katılımcı memnuniyeti, operasyonel verimlilik, bütçe başarısı ve kurumsal hedeflere katkı gibi tüm kriterleri değerlendirerek ölçülebilir başarılar üretmeyi amaçlıyoruz."}],"heroImage":"/media/corporate/degerlerimiz.webp"}'::jsonb,'published'::public.content_status,'{"title":"Değerlerimiz","description":"Başarıya Giden Yolun Temel İlkeleri"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.pages (page_key,locale,title,slug,eyebrow,summary,content_json,status,seo_json,published_at) values ('why-us','tr','Neden Biz','neden-biz','NEDEN BİZ','Sadece Organizasyon Yönetmiyoruz, Başarı Yönetiyoruz','{"headline":"Sadece Organizasyon Yönetmiyoruz, Başarı Yönetiyoruz","paragraphs":["Bir organizasyonun başarısı yalnızca etkinlik günüyle ölçülmez.","Gerçek başarı; doğru planlama, etkili koordinasyon, kontrollü bütçe yönetimi, profesyonel uygulama ve detaylı raporlama süreçlerinin tamamında ortaya çıkar.","SD Kongre olarak müşterilerimize yalnızca bir hizmet sağlayıcı değil, organizasyonun her aşamasında yanında olan stratejik bir iş ortağı yaklaşımı sunuyoruz."],"items":[{"title":"Tek Noktadan Yönetim","description":"Tüm süreçler tek merkezden planlanır ve yönetilir. Böylece farklı tedarikçiler arasında koordinasyon kaybı yaşanmaz, süreçler daha hızlı ve daha kontrollü ilerler.","icon":"network"},{"title":"Türkiye Genelinde Operasyon Gücü","description":"Türkiye genelindeki çözüm ortaklarımız ve saha ekiplerimiz sayesinde organizasyonlarınızı nerede gerçekleştirirseniz gerçekleştirin aynı kalite standartlarıyla hizmet sunuyoruz.","icon":"map"},{"title":"Teknoloji Destekli Süreçler","description":"Online kayıt sistemleri, QR kod çözümleri, katılımcı panelleri, dijital raporlama sistemleri ve hibrit etkinlik altyapıları sayesinde süreçleri daha verimli hale getiriyoruz.","icon":"cpu"},{"title":"Şeffaf Bütçe Yönetimi","description":"Her harcama kalemi planlanır, izlenir ve raporlanır. Böylece bütçeniz üzerinde tam kontrol sağlarsınız.","icon":"wallet"},{"title":"Deneyimli Uzman Kadro","description":"Yılların deneyimine sahip proje yöneticileri, operasyon uzmanları ve teknik ekiplerimizle süreçlerin her aşamasını profesyonel şekilde yönetiyoruz.","icon":"users"},{"title":"Ölçülebilir Sonuçlar","description":"Her organizasyon sonrasında performans verileri, bütçe analizleri, katılımcı istatistikleri ve memnuniyet raporları sunarak yatırımınızın karşılığını somut verilerle ortaya koyuyoruz.","icon":"chart"}],"heroImage":"/media/headers/neden-biz.webp"}'::jsonb,'published'::public.content_status,'{"title":"Neden Biz","description":"Sadece Organizasyon Yönetmiyoruz, Başarı Yönetiyoruz"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,page_key) do update set title=excluded.title,slug=excluded.slug,eyebrow=excluded.eyebrow,summary=excluded.summary,content_json=excluded.content_json,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('physical','tr','Lansman ve Kurumsal Etkinlikler','lansman-ve-kurumsal-etkinlikler','Markanızın Hikâyesini Etkileyici Bir Deneyime Dönüştürüyoruz.','{"paragraphs":["Yeni bir ürünün, hizmetin veya markanın pazara sunulması, kurumunuz için kritik öneme sahip stratejik bir adımdır. İlk izlenimlerin güçlü olduğu, hedef kitlenin markanızla duygusal bağ kurduğu bu süreçte profesyonel organizasyon yönetimi büyük fark yaratır.","SD Kongre olarak markanızın vizyonunu, kurumsal kimliğini ve vermek istediği mesajı analiz ederek hedef kitleniz üzerinde güçlü etki bırakacak etkinlikler tasarlıyoruz.","Etkinliğin ilk konsept çalışmasından son misafir uğurlanana kadar tüm süreçleri titizlikle yönetiyoruz.","Amacımız yalnızca bir etkinlik düzenlemek değil; markanızın hedef kitlesiyle güçlü bağ kurmasını sağlayan unutulmaz deneyimler oluşturmaktır."],"features":[],"imageUrl":"/media/services/physical/lansman-ve-kurumsal-etkinlikler.webp","imageAlt":"Lansman ve Kurumsal Etkinlikler hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'sparkles',1,'published'::public.content_status,'{"title":"Lansman ve Kurumsal Etkinlikler","description":"Markanızın Hikâyesini Etkileyici Bir Deneyime Dönüştürüyoruz."}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('physical','tr','Kongre Organizasyonları','kongre-organizasyonlari','Organizasyonlarınızda profesyonel yönetim anlayışıyla mükemmel sonuçlar hedefliyoruz.','{"paragraphs":["Kongre organizasyonları, yüksek katılımcı sayısı, çok paydaşlı yapısı ve detaylı operasyon süreçleri nedeniyle profesyonel yönetim gerektiren etkinliklerdir.","SD Kongre olarak ulusal ve uluslararası kongrelerin tüm planlama ve uygulama süreçlerini uzman ekiplerimizle yönetiyor, akademik ve bilimsel organizasyonların başarıyla yürütülmesini sağlıyoruz.","Bilimsel kurulların koordinasyonundan sponsorluk yönetimine, kayıt sistemlerinden katılımcı deneyimine kadar tüm süreçleri tek merkezden kontrol ediyoruz.","Kongrenizin akademik başarısını destekleyen, katılımcı deneyimini güçlendiren ve kurumsal itibarınızı yükselten profesyonel çözümler sunuyoruz."],"features":[],"imageUrl":"/media/services/physical/kongre-organizasyonlari.webp","imageAlt":"Kongre Organizasyonları hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'presentation',2,'published'::public.content_status,'{"title":"Kongre Organizasyonları","description":"Organizasyonlarınızda profesyonel yönetim anlayışıyla mükemmel sonuçlar hedefliyoruz."}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('physical','tr','Toplantı ve Sempozyum Yönetimi','toplanti-ve-sempozyum-yonetimi','Verimli, Kontrollü ve Hedef Odaklı Organizasyonlar için buradayız.','{"paragraphs":["Kurumsal toplantılar ve sempozyumlar, bilgi paylaşımının yanı sıra kurumların stratejik hedeflerine ulaşmasına katkı sağlayan önemli organizasyonlardır.","SD Kongre olarak toplantılarınızın her aşamasını planlıyor, katılımcı deneyimini artıran ve operasyonel verimliliği sağlayan profesyonel çözümler geliştiriyoruz.","İster küçük ölçekli yönetici toplantıları ister yüzlerce kişinin katıldığı kapsamlı sempozyumlar olsun; organizasyonun tüm süreçlerini eksiksiz şekilde yönetiyoruz."],"features":[],"imageUrl":"/media/services/physical/toplanti-ve-sempozyum-yonetimi.webp","imageAlt":"Toplantı ve Sempozyum Yönetimi hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'messages',3,'published'::public.content_status,'{"title":"Toplantı ve Sempozyum Yönetimi","description":"Verimli, Kontrollü ve Hedef Odaklı Organizasyonlar için buradayız."}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('physical','tr','Workshop Organizasyonları','workshop-organizasyonlari','Etkileşimi ve Öğrenmeyi Güçlendiren Profesyonel Çözümler sunmak için her türlü talebinizi eksiksiz olarak yönetiyoruz.','{"paragraphs":["Workshop ve eğitim etkinlikleri, katılımcılarla doğrudan etkileşim kurulmasını sağlayan özel organizasyonlardır. Bu tür etkinliklerde teknik detaylar ve operasyonel süreçlerin kusursuz yönetimi büyük önem taşır.","SD Kongre olarak eğitim ve workshop organizasyonlarında verimli öğrenme ortamları oluşturuyor, katılımcı deneyimini üst seviyeye taşıyoruz."],"features":[],"imageUrl":"/media/services/physical/workshop-organizasyonlari.webp","imageAlt":"Workshop Organizasyonları hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'workflow',4,'published'::public.content_status,'{"title":"Workshop Organizasyonları","description":"Etkileşimi ve Öğrenmeyi Güçlendiren Profesyonel Çözümler sunmak için her türlü talebinizi eksiksiz olarak yönetiyoruz."}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('physical','tr','Fuar ve Sergi Organizasyonları','fuar-ve-sergi-organizasyonlari','Markanızı Daha Fazla Kişiyle Buluşturuyoruz','{"paragraphs":["Fuarlar ve sergiler, markaların görünürlüğünü artırdığı, potansiyel müşterilerle doğrudan iletişim kurduğu ve sektördeki konumunu güçlendirdiği önemli platformlardır.","SD Kongre olarak yaratıcı tasarım anlayışını profesyonel operasyon yönetimiyle birleştirerek markanızın hedef kitlesi üzerinde güçlü etki yaratmasını sağlıyoruz."],"features":[],"imageUrl":"/media/services/physical/fuar-ve-sergi-organizasyonlari.webp","imageAlt":"Fuar ve Sergi Organizasyonları hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'landmark',5,'published'::public.content_status,'{"title":"Fuar ve Sergi Organizasyonları","description":"Markanızı Daha Fazla Kişiyle Buluşturuyoruz"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('physical','tr','Seyahat ve Konaklama Yönetimi','seyahat-ve-konaklama-yonetimi','Katılımcılarınız İçin Kusursuz Seyahat Deneyimi','{"paragraphs":["Başarılı bir organizasyonun temel unsurlarından biri de katılımcıların seyahat ve konaklama süreçlerinin eksiksiz yönetilmesidir.","SD Kongre olarak konuşmacılar, davetliler, protokol üyeleri ve katılımcılar için profesyonel seyahat planlaması gerçekleştiriyor, tüm süreçlerin sorunsuz ilerlemesini sağlıyoruz.","Katılımcılarınızın etkinliğe odaklanmasını sağlıyor, tüm lojistik detayları sizin yerinize yönetiyoruz."],"features":[],"imageUrl":"/media/services/physical/seyahat-ve-konaklama-yonetimi.webp","imageAlt":"Seyahat ve Konaklama Yönetimi hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'hotel',6,'published'::public.content_status,'{"title":"Seyahat ve Konaklama Yönetimi","description":"Katılımcılarınız İçin Kusursuz Seyahat Deneyimi"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('physical','tr','Transfer ve Lojistik Yönetimi','transfer-ve-lojistik-yonetimi','Organizasyonun Görünmeyen Gücünü Yönetiyoruz','{"paragraphs":["Organizasyonların başarısında lojistik süreçler kritik rol oynar. Doğru planlanmamış transfer ve lojistik operasyonları, etkinliğin genel başarısını doğrudan etkileyebilir.","SD Kongre olarak tüm lojistik süreçleri detaylı operasyon planları doğrultusunda yürütüyor, katılımcı hareketlerini ve ekipman akışını kusursuz şekilde yönetiyoruz."],"features":[],"imageUrl":"/media/services/physical/transfer-ve-lojistik-yonetimi.webp","imageAlt":"Transfer ve Lojistik Yönetimi hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'bus',7,'published'::public.content_status,'{"title":"Transfer ve Lojistik Yönetimi","description":"Organizasyonun Görünmeyen Gücünü Yönetiyoruz"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('physical','tr','Tedarikçi ve Operasyon Yönetimi','tedarikci-ve-operasyon-yonetimi','Doğru İş Ortaklarıyla Kusursuz Sonuçlar','{"paragraphs":["Organizasyonların başarısı yalnızca iyi bir planlamaya değil, aynı zamanda doğru tedarikçilerin etkin şekilde yönetilmesine bağlıdır.","SD Kongre olarak yıllar içerisinde oluşturduğumuz güçlü iş ortaklığı ağı sayesinde organizasyonun ihtiyaç duyduğu tüm hizmetleri kalite standartları çerçevesinde yönetiyoruz.","Teknik ekiplerden dekorasyon firmalarına, catering hizmetlerinden ulaşım sağlayıcılarına kadar tüm tedarikçilerin seçimi, koordinasyonu ve performans takibini gerçekleştiriyoruz.","SD Kongre ile çalıştığınızda yalnızca bir organizasyon firmasıyla değil; onlarca farklı süreci sizin adınıza yöneten, riskleri azaltan ve etkinliğinizin başarısını güvence altına alan profesyonel bir proje yönetim ekibiyle çalışmış olursunuz. Bu sayede siz hedeflerinize odaklanırken, biz organizasyonunuzun her detayını kusursuz şekilde yönetiriz."],"features":[],"imageUrl":"/media/services/physical/tedarikci-ve-operasyon-yonetimi.webp","imageAlt":"Tedarikçi ve Operasyon Yönetimi hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'clipboard',8,'published'::public.content_status,'{"title":"Tedarikçi ve Operasyon Yönetimi","description":"Doğru İş Ortaklarıyla Kusursuz Sonuçlar"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('digital','tr','Katılımcı ve Kayıt Yönetimi','katilimci-ve-kayit-yonetimi','Katılımcı Deneyimini Başlangıç Noktasında Güçlendiriyoruz','{"paragraphs":["Bir organizasyonun başarısı, katılımcının ilk kayıt işlemiyle başlar. Karmaşık ve zaman alan kayıt süreçleri hem katılımcı memnuniyetini düşürür hem de organizasyon ekibine ek operasyonel yük oluşturur.","SD Kongre tarafından geliştirilen dijital kayıt sistemleri sayesinde katılımcılar hızlı ve kolay şekilde kayıt oluşturabilirken organizasyon ekipleri de tüm süreci anlık olarak takip edebilmektedir.","Sağladığımız çözümler; online kayıt sistemleri, kişiselleştirilebilir katılım formları, online ödeme entegrasyonları, katılımcı veri yönetimi ve dijital check-in çözümleridir.","Bu sayede kayıt süreçleri daha hızlı ilerlerken hata oranları minimum seviyeye indirilmektedir."],"features":[],"imageUrl":"/media/services/digital/katilimci-ve-kayit-yonetimi.webp","imageAlt":"Katılımcı ve Kayıt Yönetimi hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'user-check',1,'published'::public.content_status,'{"title":"Katılımcı ve Kayıt Yönetimi","description":"Katılımcı Deneyimini Başlangıç Noktasında Güçlendiriyoruz"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('digital','tr','Dijital Altyapı ve Etkinlik Teknolojileri','dijital-altyapi-ve-etkinlik-teknolojileri','Organizasyonlarınızı Geleceğin Teknolojileriyle Güçlendiriyoruz','{"paragraphs":["Günümüz etkinlik dünyasında teknoloji artık bir tercih değil, bir gereklilik haline gelmiştir. SD Kongre olarak organizasyonlarınıza yenilikçi teknolojiler entegre ederek katılımcı deneyimini artırıyor, operasyonel yönetimi kolaylaştırıyor ve organizasyon performansını üst seviyeye taşıyoruz.","Sunulan teknolojik çözümler; kayıt ve yönetim yazılımları, canlı yayın sistemleri, online katılım altyapıları, hibrit etkinlik çözümleri, etkinlik web siteleri, dijital sponsorluk alanları, etkileşim ve geri bildirim sistemleridir.","Teknoloji destekli çözümlerimiz sayesinde hem fiziksel hem dijital katılımcılar için kesintisiz etkinlik deneyimi sunuyoruz."],"features":[],"imageUrl":"/media/services/digital/dijital-altyapi-ve-etkinlik-teknolojileri.webp","imageAlt":"Dijital Altyapı ve Etkinlik Teknolojileri hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'monitor',2,'published'::public.content_status,'{"title":"Dijital Altyapı ve Etkinlik Teknolojileri","description":"Organizasyonlarınızı Geleceğin Teknolojileriyle Güçlendiriyoruz"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('digital','tr','QR Kod ve Yaka Kart Sistemleri','qr-kod-ve-yaka-kart-sistemleri','Hızlı, Güvenli ve Temassız Katılım Yönetimi','{"paragraphs":["Yüksek katılımcı sayısına sahip etkinliklerde giriş süreçlerinin hızlı ve hatasız yönetilmesi büyük önem taşır. QR kod entegrasyonlu dijital kontrol sistemlerimiz sayesinde katılımcı girişleri saniyeler içerisinde gerçekleştirilebilir ve tüm süreç anlık olarak izlenebilir.","Bu sistemler sayesinde organizasyonlar daha kontrollü, güvenli ve profesyonel şekilde yönetilmektedir."],"features":[],"imageUrl":"/media/services/digital/qr-kod-ve-yaka-kart-sistemleri.webp","imageAlt":"QR Kod ve Yaka Kart Sistemleri hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'qr',3,'published'::public.content_status,'{"title":"QR Kod ve Yaka Kart Sistemleri","description":"Hızlı, Güvenli ve Temassız Katılım Yönetimi"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('digital','tr','Online Davet ve İletişim Yönetimi','online-davet-ve-iletisim-yonetimi','Katılımcılarınızla Güçlü ve Kesintisiz İletişim Kurun','{"paragraphs":["Organizasyon başarısında doğru iletişim stratejileri kritik rol oynar. Katılımcılarla zamanında ve etkili iletişim kurulması, katılım oranlarını doğrudan etkileyen faktörlerden biridir.","SD Kongre olarak davet süreçlerini dijital platformlara taşıyor, profesyonel tasarımlı iletişim sistemleri ile hedef kitlenizle güçlü bağlar kurmanızı sağlıyoruz."],"features":[],"imageUrl":"/media/services/digital/online-davet-ve-iletisim-yonetimi.webp","imageAlt":"Online Davet ve İletişim Yönetimi hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'mail',4,'published'::public.content_status,'{"title":"Online Davet ve İletişim Yönetimi","description":"Katılımcılarınızla Güçlü ve Kesintisiz İletişim Kurun"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('digital','tr','Organizasyon Takip Sistemleri','organizasyon-takip-sistemleri','Projenizin Her Aşamasını Gerçek Zamanlı Olarak Yönetin','{"paragraphs":["Büyük ölçekli organizasyonlarda onlarca farklı sürecin eş zamanlı yürütülmesi gerekmektedir.","SD Kongre tarafından kullanılan dijital proje takip sistemleri sayesinde organizasyonun hangi aşamada olduğu, hangi görevlerin tamamlandığı ve hangi süreçlerin devam ettiği anlık olarak görüntülenebilmektedir.","Bu yapı sayesinde müşterilerimiz süreçler üzerinde tam görünürlük elde ederken proje yönetimi daha kontrollü hale gelmektedir."],"features":[],"imageUrl":"/media/services/digital/organizasyon-takip-sistemleri.webp","imageAlt":"Organizasyon Takip Sistemleri hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'list-checks',5,'published'::public.content_status,'{"title":"Organizasyon Takip Sistemleri","description":"Projenizin Her Aşamasını Gerçek Zamanlı Olarak Yönetin"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('digital','tr','Veri ve Raporlama Sistemleri','veri-ve-raporlama-sistemleri','Organizasyonlarınızı Verilerle Ölçülebilir Hale Getiriyoruz','{"paragraphs":["Başarılı organizasyonlar yalnızca uygulanan değil, analiz edilen organizasyonlardır.","Bu nedenle etkinlik sonunda kapsamlı veri analizleri ve profesyonel raporlama hizmetleri sunuyoruz.","Elde edilen veriler sayesinde kurumlar yatırım geri dönüşlerini değerlendirebilir, güçlü yönlerini görebilir ve gelecekteki projelerini daha verimli planlayabilir."],"features":[],"imageUrl":"/media/services/digital/veri-ve-raporlama-sistemleri.webp","imageAlt":"Veri ve Raporlama Sistemleri hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'chart',6,'published'::public.content_status,'{"title":"Veri ve Raporlama Sistemleri","description":"Organizasyonlarınızı Verilerle Ölçülebilir Hale Getiriyoruz"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
insert into public.services (category,locale,title,slug,summary,body_json,icon,order_no,status,seo_json,published_at) values ('digital','tr','Veri Güvenliği ve Merkezi Yönetim','veri-guvenligi-ve-merkezi-yonetim','Verilerinizi En Yüksek Güvenlik Standartlarıyla Koruyoruz','{"paragraphs":["Dijitalleşmenin en önemli unsurlarından biri veri güvenliğidir.","SD Kongre olarak tüm katılımcı ve kurumsal verileri güvenli altyapılarda saklıyor, KVKK ve ilgili mevzuat hükümlerine uygun şekilde işliyoruz.","Veri güvenliğini yalnızca teknik bir gereklilik değil, kurumsal sorumluluğumuzun ayrılmaz bir parçası olarak görüyoruz. Güvenlik yaklaşımımız; KVKK uyumlu veri yönetimi, yetkilendirilmiş erişim sistemleri, güvenli veri saklama altyapıları, merkezi yönetim panelleri ve veri erişim kontrol mekanizmalarından oluşmaktadır."],"features":[],"imageUrl":"/media/services/digital/veri-guvenligi-ve-merkezi-yonetim.webp","imageAlt":"Veri Güvenliği ve Merkezi Yönetim hizmetini temsil eden görsel","animation":"fade"}'::jsonb,'shield',7,'published'::public.content_status,'{"title":"Veri Güvenliği ve Merkezi Yönetim","description":"Verilerinizi En Yüksek Güvenlik Standartlarıyla Koruyoruz"}'::jsonb,'2026-08-06T00:00:00.000Z'::timestamptz) on conflict (locale,category,slug) do update set title=excluded.title,summary=excluded.summary,body_json=excluded.body_json,icon=excluded.icon,order_no=excluded.order_no,status=excluded.status,seo_json=excluded.seo_json,published_at=excluded.published_at,updated_at=now();
